require __DIR__.'/includes/bootstrap.php';require_role('admin');require __DIR__.'/includes/bank.php';$page_title='Интеграция с банком';$s=$pdo->query('SELECT outcome,COUNT(*) AS total FROM bank_api_logs GROUP BY outcome');$counts=$s->fetchAll();$logs=$pdo->query('SELECT l.*,f.external_ref FROM bank_api_logs l LEFT JOIN fines f ON f.id=l.fine_id ORDER BY l.created_at DESC LIMIT 30')->fetchAll();include __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow">Администрирование</span><h1>Интеграция с «Капитал-Стандарт»</h1><p>Настройки API, результат передачи начислений и история запросов.</p></section>
<section class="panel panel-pad" style="margin-bottom:18px"><div class="section-head"><div><h2>Статус подключения</h2><p>Секретный ключ в интерфейсе никогда не показывается.</p></div><span class="badge <?= bank_is_configured($config)?'badge-green':'badge-yellow' ?>"><?= bank_is_configured($config)?'Конфигурация задана':'Требуется настройка' ?></span></div><div class="summary-row"><span>API endpoint</span><strong><?= $config['bank']['api_url']?e($config['bank']['api_url']):'Не указан' ?></strong></div><div class="summary-row"><span>API-ключ</span><strong><?= bank_is_configured($config)?'Установлен · скрыт':'Не настроен' ?></strong></div><div class="summary-row"><span>HTTP-механизм</span><strong>POST · application/json</strong></div><div class="summary-row"><span>Заголовок авторизации</span><strong>X-API-Key</strong></div><div class="divider"></div><h3>Как включить интеграцию</h3><p class="muted tiny" style="line-height:1.9">1. Скопируйте <code>config.local.php.example</code> в <code>config.local.php</code>.<br>2. Впишите реальный URL сайта банка, заканчивающийся на <code>/api.php</code>, и активный API-ключ.<br>3. Убедитесь, что сервер может исходящими HTTP-запросами обратиться к банку и имеет cURL (рекомендуется) либо разрешённый HTTPS stream wrapper.<br>4. Перевыпустите ключ, который был опубликован в сообщении или скриншоте.</p></section>
<section class="panel"><div class="panel-header"><h2>Последние обращения к API</h2><p>Секреты авторизации в журнал не записываются.</p></div><?php if($logs): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Постановление</th><th>Результат</th><th>HTTP</th><th>Ответ / ошибка</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= e(date('d.m.Y H:i:s',strtotime($l['created_at']))) ?></td><td><?= e($l['external_ref']?:('#'.$l['fine_id'])) ?></td><td><span class="badge <?= $l['outcome']==='sent'?'badge-green':'badge-red' ?>"><?= e(status_label($l['outcome'])) ?></span></td><td><?= (int)$l['http_code'] ?: '—' ?></td><td style="white-space:normal;max-width:430px"><?= e(mb_substr((string)$l['response_excerpt'],0,220)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">⌘</div><h2>Запросов пока нет</h2><p>Когда сотрудник оформит штраф, результат взаимодействия с API появится здесь.</p></div><?php endif; ?></section>
